<?php $bodyClass = 'internal-page'; ?>
<main id="conteudo" class="catalog-page"><nav class="catalog-breadcrumb"><div class="container"><a href="<?= url('/') ?>">Início</a><span>/</span><span>Produtos</span></div></nav><section class="catalog-hero"><div class="container"><span class="eyebrow">Catálogo</span><h1><?= e($search ? 'Busca: “' . $search . '”' : 'Todos os produtos') ?></h1><p><?= count($products) ?> produtos encontrados</p></div></section><section class="section catalog-content"><div class="container"><form class="catalog-search" action="<?= url('/produtos') ?>"><input type="search" name="busca" value="<?= e($search) ?>" placeholder="Buscar produtos"><button class="button button-primary">Buscar</button></form><div class="catalog-filters"><a class="<?= $selectedCategory === '' ? 'is-active' : '' ?>" href="<?= url('/produtos') ?>">Todos</a><?php foreach ($categories as $category): ?><a class="<?= $selectedCategory === $category['slug'] ? 'is-active' : '' ?>" href="<?= url('/produtos?categoria=' . rawurlencode($category['slug'])) ?>"><?= e($category['name']) ?></a><?php endforeach; ?></div><div class="catalog-grid"><?php foreach ($products as $product): ?><?php require ROOT_PATH . '/app/Views/partials/product-card.php'; ?><?php endforeach; ?></div><?php if (!$products): ?><p class="catalog-empty">Nenhum produto encontrado.</p><?php endif; ?></div></section></main>

